INSERT INTO private.baseline_bank(qualification,academic_level,position,topic,skill,difficulty,prompt,choices,correct_text,explanation) VALUES
('A_LEVEL','as',1,'Functions','Evaluating functions',2,'If f(x) = 2x² − 5x + 1, find f(3).',jsonb_build_array('2','4','7','16'),'4','f(3) = 2(9) − 15 + 1 = 4.'),
('A_LEVEL','as',2,'Functions','Inverse functions',3,'If f(x) = 3x − 7, find f⁻¹(x).',jsonb_build_array('(x − 7)/3','3x + 7','(x + 7)/3','(7 − x)/3'),'(x + 7)/3','Write y = 3x − 7; rearrange x = (y + 7)/3.'),
('A_LEVEL','as',3,'Functions','Composition',3,'If f(x) = 2x + 3 and g(x) = x² − 1, simplify f(g(x)).',jsonb_build_array('2x² + 1','2x² − 1','(2x + 3)² − 1','x² + 5'),'2x² + 1','f(g(x)) = 2(x² − 1) + 3 = 2x² + 1.'),
('A_LEVEL','as',4,'Quadratics','Completing the square',3,'Write x² + 6x + 2 in completed-square form.',jsonb_build_array('(x + 3)² + 7','(x − 3)² − 7','(x + 3)² − 7','(x + 6)² − 34'),'(x + 3)² − 7','(x + 3)² = x² + 6x + 9, so subtract 7.'),
('A_LEVEL','as',5,'Quadratics','Solving equations',2,'Find both roots of x² − 8x + 15 = 0.',jsonb_build_array('−3 and −5','3 and 5','1 and 15','−1 and −15'),'3 and 5','Factor as (x − 3)(x − 5) = 0.'),
('A_LEVEL','as',6,'Quadratics','Discriminant',3,'How many distinct real solutions has x² − 4x + 4 = 0?',jsonb_build_array('0','1','2','4'),'1','The discriminant is (−4)² − 4(1)(4) = 0, so there is one repeated root.'),
('A_LEVEL','as',7,'Binomial expansion','Binomial coefficient',3,'Find the coefficient of x² in (1 + 2x)⁴.',jsonb_build_array('8','16','24','32'),'24','The coefficient is C(4,2)×2² = 6×4 = 24.'),
('A_LEVEL','as',8,'Sequences and series','Arithmetic progression',3,'Find the sum of the first 10 terms of 3, 7, 11, 15, ...',jsonb_build_array('190','200','210','220'),'210','S₁₀ = (10/2)(2×3 + 9×4) = 5×42 = 210.'),
('A_LEVEL','as',9,'Sequences and series','Geometric progression',3,'A geometric sequence begins 5, 10, 20, ... . Find its fifth term.',jsonb_build_array('40','60','75','80'),'80','The fifth term is 5 × 2⁴ = 80.'),
('A_LEVEL','as',10,'Differentiation','Power rule',2,'Differentiate y = x³ − 4x² + 2 with respect to x.',jsonb_build_array('3x² − 8x','3x² − 4x','x² − 8x','3x³ − 8x'),'3x² − 8x','Differentiate each term: 3x² − 8x + 0.'),
('A_LEVEL','as',11,'Differentiation','Stationary points',3,'At what x-coordinate is y = x² − 6x + 2 stationary?',jsonb_build_array('−3','2','3','6'),'3','dy/dx = 2x − 6; set to zero to obtain x = 3.'),
('A_LEVEL','as',12,'Integration','Indefinite integrals',3,'Integrate 6x² − 4x with respect to x.',jsonb_build_array('18x − 4','2x³ − 2x² + C','6x³ − 4x² + C','2x³ − 4x + C'),'2x³ − 2x² + C','Increase powers and divide by the new powers.'),
('A_LEVEL','as',13,'Trigonometry','Elementary trig equations',3,'For 0° ≤ x ≤ 90°, solve 2sin x = 1.',jsonb_build_array('15°','30°','45°','60°'),'30°','sin x = 1/2, so x = 30° within the given interval.'),
('A_LEVEL','as',14,'Trigonometry','Cosine rule',4,'Two sides of a triangle are 5 cm and 7 cm with included angle 60°. Find the third side.',jsonb_build_array('√39 cm','√74 cm','6 cm','√109 cm'),'√39 cm','By the cosine rule, c² = 25 + 49 − 2×5×7×cos60° = 39.'),
('A_LEVEL','as',15,'Trigonometry','Sine rule',3,'In a triangle, the side opposite 30° is 5 cm. What is the side opposite 90°?',jsonb_build_array('5 cm','5√2 cm','10 cm','15 cm'),'10 cm','By sine rule b = 5×sin90°/sin30° = 10 cm.'),
('A_LEVEL','as',16,'Geometry','Three-dimensional Pythagoras',3,'A cuboid has edges of length 3 cm, 4 cm and 12 cm. Find its space diagonal.',jsonb_build_array('12 cm','13 cm','15 cm','19 cm'),'13 cm','d = √(3² + 4² + 12²) = √169 = 13 cm.'),
('A_LEVEL','as',17,'Coordinate geometry','Equation of a circle',3,'Find the equation of a circle with centre (2, −3) and radius 5.',jsonb_build_array('(x + 2)² + (y − 3)² = 25','(x − 2)² + (y + 3)² = 25','(x − 2)² + (y − 3)² = 5','(x + 2)² + (y + 3)² = 25'),'(x − 2)² + (y + 3)² = 25','The standard form is (x−a)² + (y−b)² = r².'),
('A_LEVEL','as',18,'Integration','Area under a straight line',3,'Find the area under y = 2x, above the x-axis, from x = 0 to x = 3.',jsonb_build_array('3','6','9','18'),'9','Area is a triangle with base 3 and height 6: 1/2 ×3×6 = 9.'),
('A_LEVEL','as',19,'Inequalities','Quadratic inequalities',4,'Solve x² − 5x + 6 > 0.',jsonb_build_array('2 < x < 3','x < 2 or x > 3','x ≤ 2 or x ≥ 3','x > 2'),'x < 2 or x > 3','(x − 2)(x − 3) is positive outside the roots; strict inequality excludes endpoints.'),
('A_LEVEL','as',20,'Algebra','Simplifying algebraic fractions',3,'Simplify (x² − 16)/(x + 4), given x ≠ −4.',jsonb_build_array('x + 4','x − 4','(x−4)/(x+4)','x² − 4'),'x − 4','Factor (x−4)(x+4), then cancel (x+4), with x ≠ −4.')
INSERT INTO private.baseline_bank(qualification,academic_level,position,topic,skill,difficulty,prompt,choices,correct_text,explanation) VALUES
('A_LEVEL','a2',1,'Differentiation','Product rule',4,'If y = x² sin x, find dy/dx at x = π/2 (in radians).',jsonb_build_array('0','π','π²/4','2π'),'π','Product rule gives 2x sin x + x² cos x. At π/2 this is π.'),
('A_LEVEL','a2',2,'Integration','Definite integral',3,'Evaluate ∫₀²(3x² + 2x) dx.',jsonb_build_array('8','10','12','16'),'12','Antiderivative x³ + x² gives 8 + 4 = 12.'),
('A_LEVEL','a2',3,'Exponentials','Exponential equations',3,'Solve 2^(x+1) = 16.',jsonb_build_array('2','3','4','5'),'3','16 = 2⁴, so x + 1 = 4 and x = 3.'),
('A_LEVEL','a2',4,'Logarithms','Logarithmic equations',3,'Solve log₂(x − 1) = 3.',jsonb_build_array('7','8','9','10'),'9','x − 1 = 2³ = 8, so x = 9.'),
('A_LEVEL','a2',5,'Trigonometry','Trigonometric equations',3,'Find the only solution of tan x = 1 for 0° ≤ x < 180°.',jsonb_build_array('30°','45°','90°','135°'),'45°','tan 45° = 1; the next solution is 225°, outside the interval.'),
('A_LEVEL','a2',6,'Trigonometry','Trigonometric identities',3,'Which identity holds for every real angle θ?',jsonb_build_array('sin²θ + cos²θ = 1','sinθ + cosθ = 1','tan²θ = 1 − cos²θ','sin²θ − cos²θ = 1'),'sin²θ + cos²θ = 1','This is the Pythagorean trigonometric identity.'),
('A_LEVEL','a2',7,'Differentiation','Chain rule',4,'Differentiate (3x + 1)⁵.',jsonb_build_array('5(3x + 1)⁴','15(3x + 1)⁴','(3x+1)⁶/6','15(3x + 1)⁵'),'15(3x + 1)⁴','The outer derivative is 5(3x + 1)⁴; multiply by the inner derivative 3.'),
('A_LEVEL','a2',8,'Differentiation','Logarithmic differentiation',3,'Find d/dx[ln(2x)] for x > 0.',jsonb_build_array('1/(2x)','2/x','1/x','2'),'1/x','Chain rule: (1/(2x))×2 = 1/x.'),
('A_LEVEL','a2',9,'Integration','Exponential integration',4,'Integrate e^(2x) with respect to x.',jsonb_build_array('2e^(2x)+C','(1/2)e^(2x)+C','e^(2x)+C','e^(x²)+C'),'(1/2)e^(2x)+C','The derivative of e^(2x) is 2e^(2x); divide by 2.'),
('A_LEVEL','a2',10,'Sequences and series','Convergent geometric series',3,'An infinite geometric series has first term 12 and common ratio 1/4. Find its sum.',jsonb_build_array('12','15','16','48'),'16','Sum = 12/(1−1/4) = 16.'),
('A_LEVEL','a2',11,'Binomial expansion','Coefficient extraction',4,'Find the coefficient of x² in (1 + 3x)⁵.',jsonb_build_array('45','60','90','135'),'90','C(5,2)×3² = 10×9 = 90.'),
('A_LEVEL','a2',12,'Statistics','Standardising a normal variable',3,'A normal variable has mean 60 and standard deviation 6. Find the z-score of 72.',jsonb_build_array('1','2','3','12'),'2','z=(72−60)/6=2.'),
('A_LEVEL','a2',13,'Probability','Poisson probabilities',4,'If X has Poisson distribution with mean 3, find P(X=0).',jsonb_build_array('3e⁻³','e⁻³','1−e⁻³','e³'),'e⁻³','P(X=0) = e⁻³·3⁰/0! = e⁻³.'),
('A_LEVEL','a2',14,'Differential equations','Separable differential equations',5,'A function satisfies dy/dx = 2xy and y(0) = 3. Which is y(x)?',jsonb_build_array('3e^(2x)','3e^(x²)','e^(3x²)','3x²'),'3e^(x²)','Separate dy/y=2x dx, giving ln y = x² + C and y=3e^(x²).'),
('A_LEVEL','a2',15,'Vectors','Scalar products',3,'Calculate (1, 2, 2) · (3, 1, −2).',jsonb_build_array('−3','1','3','9'),'1','1×3 + 2×1 + 2×(−2) = 1.'),
('A_LEVEL','a2',16,'Parametric equations','Parametric gradients',4,'For x = t² and y = t³, find dy/dx at t = 2.',jsonb_build_array('2','3','4','6'),'3','dy/dx=(3t²)/(2t) = 3t/2, giving 3 at t=2.'),
('A_LEVEL','a2',17,'Integration','Integration by parts',5,'Evaluate ∫x eˣ dx (include a constant C).',jsonb_build_array('(x − 1)eˣ + C','(x + 1)eˣ + C','xeˣ + C','eˣ/x + C'),'(x − 1)eˣ + C','Integration by parts with u=x gives xeˣ−eˣ+C.'),
('A_LEVEL','a2',18,'Differentiation','Classifying stationary points',4,'For y = x³ − 3x, which x-coordinate is a local maximum?',jsonb_build_array('−1','0','1','3'),'−1','y′=3x²−3, stationary at ±1; y″=6x is negative at x=−1.'),
('A_LEVEL','a2',19,'Logarithms','Combining logarithms',4,'Solve ln x + ln(x − 1) = ln 6 for x > 1.',jsonb_build_array('2','3','4','6'),'3','ln[x(x−1)] = ln6; x²−x−6=0 gives x=3 (since x>1).'),
('A_LEVEL','a2',20,'Mechanics','Constant acceleration',3,'A particle has initial speed 5 m/s and constant acceleration 2 m/s² for 4 s. Find its displacement.',jsonb_build_array('28 m','32 m','36 m','40 m'),'36 m','s=ut+(1/2)at² =5×4+0.5×2×4² =36 m.')
